from pathlib import Path
from simulation import Simulation
s=Simulation(Path(__file__).resolve().parent.parent);s.stopped.set();s.thread.join()
try:
 print(s.eval(r'''
local J=require('game.json');local P=require('game.profile');local C=require('game.caves');local w=SG_SERVER.world;C.ensure(w);local entry=assert(w.caveEntrances[1]);local sk=require('game.skills').new();sk.data.Religion.xp=sk.xpTable[30];sk.data.Religion.level=30;local inv=require('game.inventory').new();inv:add('Copper Axe',1);local player=require('game.player').new();player.x,player.y=300,300;player.hp=0
local b={worldId=require('game.regions').doc.worldId,regionId=require('game.regions').start,area='cave',caveId=entry.id,caveSeed=entry.seed,id=99,slot=1,owner='qa',name='Cave Tester',race='Human',initial=true,seq=1,religionBaseline=sk.xpTable[30],personal=P.pack({player=player,skills=sk.data,bags=inv.bagSlots,equipment={},potionBelt={}})}
SG_CALL('exchange',J.encode(b));SG_CALL('tick',J.encode({dt=.05,time=1}));b.seq=2;b.initial=false;local reply=J.decode(SG_CALL('exchange',J.encode(b)));assert(reply.deathCaveExit,'Death directs client out of cave');local saved=P.unpack(reply.personal);assert(not next(saved.bags),'Cave death transferred bags');local snapshot=P.unpack(reply.snapshot);local g=assert(snapshot.gravestones[1]);assert(g.x==300 and g.y==300 and g.hp==50 and not g.contents,'Grave stays private at cave death coordinates');local x,y=require('game.respawn').town(w,entry.x,entry.y);assert(math.abs(saved.player.x-x)<.01 and math.abs(saved.player.y-y)<.01,'Respawn is nearest overworld town')
local instance=assert(w.caveInstances[entry.id]);for _,e in ipairs(instance.enemies)do e.dead=true;e.hp=0 end;assert(not C.cleared(instance),'Occupied grave prevents cleared cave deletion');local exported=C.export(w);local record;for _,v in ipairs(exported)do if v.id==entry.id then record=v end end;assert(record.state.gravestones[1].contents.bags[1].slots[1].name=='Copper Axe','Offline cave export retains contents');local restored=C.generate(w,record);assert(restored.gravestones[1].contents.bags[1].slots[1].name=='Copper Axe','Cave restore retains original bag objects');return 'PASS 8 cave death, town respawn, privacy, closure and persistence checks'
'''))
finally:s.close()
